head.script:
scwin.fireOver = function(node) {
    if (document.createEventObject) {
        node.fireEvent('onmouseover');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('mouseover', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.onmouseover == 'function') {
        node.onmouseover();
    }
}
scwin.mouseOverBehaviour = function(id, p) {
    var el = document.querySelectorAll('[id=' + id + ']');
    scwin.fireOver(el[p]);
}
scwin.getTooltip = function() {
    var el = WebSquare.wUnit.getDomById($p.id + "gridView1_tooltip");
    return el.innerText;
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 1. Design 탭에서 gridView 마우스 오른쪽 -> Footer 추가 / SubTotal 추가 버튼을 클릭한다.
    //1. On the Design tab, right-click gridView-> Add Footer / Add SubTotal.
    // verify step 1. Footer 와 SubTotal 이 추가된다.
    //1. Footer and SubTotal are added.
    //Test step 2. Property 탭 또는 Source 탭에서 gridView1 의 tooltipDisplay 부분을 확인한다.
    //2. In the Property tab or the Source tab, check the tooltipDisplay portion of gridView1.
    //Verify step 2. tooltipDisplay='true'
    //Test step 3. 브라우저에서 Footer 와 SubTotal 부분에 마우스 오버한다. 
    //3. Mouse over the Footer and SubTotal sections in the browser.
    //Verify step 3. Footer 와 SubTotal 에 대해 Tooltip 이 생성된다. (그전버전에서는 Tooltip 이 생성되지 않음)
    //3. Tooltip is created for Footer and SubTotal. (Tooltip is not created in previous versions)
    WebSquare.wUnit.addCommand("set", "scwin.mouseOverBehaviour('column3', 3)");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#gridView1_tooltip').css('display') == 'block'", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.getTooltip() == '100000000'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.mouseOverBehaviour($p.id+'gridView1_column4', 0)");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#gridView1_tooltip').css('display') == 'block'", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.getTooltip() == '100000000'", "true");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
