            "col2": ""
        },
        {
            "col1": "b",
            "col2": ""
        },
        {
            "col1": "b",
            "col2": ""
        },
        {
            "col1": "b",
            "col2": ""
        }
    ];
    dataList1.setJSON(jsonData);
    //Function unitTest
    //Created By: Sang.do
    //Created By: 30-Jan-2018
    //end unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
